interface MarkdownProps {
  children: string;
  fontSize?: number;
  disableMermaid?: boolean;
  disableSvg?: boolean;
  onEditSvg?: (svgSource: string) => void;
}

const CopyButton: React.FC<{ text: string }> = ({ text }) => {
  const [copied, setCopied] = useState(false);
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(
    () => (): void => {
      if (timerRef.current) clearTimeout(timerRef.current);
    },
    [],
  );

  const handleCopy = async (): Promise<void> => {
    try {
      await navigator.clipboard.writeText(text);
      setCopied(true);
      if (timerRef.current) clearTimeout(timerRef.current);
      timerRef.current = setTimeout(() => setCopied(false), 2000);
    } catch (err) {
      console.error('Failed to copy!', err);
    }
  };

  return (
    <IconButton
      onClick={(): void => {
        void handleCopy();
      }}
      size="small"
      aria-label={copied ? 'Copied!' : 'Copy code to clipboard'}
      className="copy-button"
      sx={{
        position: 'absolute',
        top: 8,
        right: 8,
        opacity: 0,
        transition: 'opacity 0.2s',
        color: (theme) => (theme.palette.mode === 'dark' ? 'rgba(255, 255, 255, 0.6)' : 'rgba(0, 0, 0, 0.5)'),
        '&:hover': {
          color: (theme) => (theme.palette.mode === 'dark' ? 'white' : 'black'),
          backgroundColor: (theme) => (theme.palette.mode === 'dark' ? 'rgba(255, 255, 255, 0.1)' : 'rgba(0, 0, 0, 0.05)'),
        },
        zIndex: 1,
      }}
    >
      {copied ? <Check fontSize="small" /> : <ContentCopy fontSize="small" />}
    </IconButton>
  );
};

interface MermaidProps {
  children: string;
}

const MERMAID_DEBOUNCE_MS = 300;

const MermaidDiagram: React.FC<MermaidProps> = ({ children }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    const renderDiagram = async (): Promise<void> => {
      try {
        const id = `mermaid-${crypto.randomUUID()}`;
        const { svg } = await mermaid.render(id, children.trim());
        container.innerHTML = svg;
        setError(null);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'Failed to render diagram');
      }
    };

    if (debounceRef.current) {
      clearTimeout(debounceRef.current);
    }
    debounceRef.current = setTimeout(() => {
      void renderDiagram();
    }, MERMAID_DEBOUNCE_MS);

    return () => {
      if (debounceRef.current) {
        clearTimeout(debounceRef.current);
        debounceRef.current = null;
      }
    };
  }, [children]);

  if (error) {
    return (
      <Box
        sx={{
          my: 1,
          p: 2,
          border: '1px solid',
          borderColor: 'error.main',
          borderRadius: 1,
          backgroundColor: 'error.dark',
          color: 'error.contrastText',
          fontSize: '0.875rem',
          fontFamily: 'monospace',
        }}
      >
        {error}
      </Box>
    );
  }

  return (
    <Box
      ref={containerRef}
      sx={{
        my: 2,
        display: 'flex',
        justifyContent: 'center',
        '& svg': {
          maxWidth: '100%',
          height: 'auto',
        },
      }}
    />
  );
};

type SvgBackground = 'light' | 'dark' | 'transparent';

const SVG_BACKGROUND_COLORS: Record<SvgBackground, string> = {
  light: '#ffffff',
  dark: '#1e1e1e',
  transparent: 'transparent',
};

interface SvgDiagramProps {
  children: string;
  onEditSvg?: (svgSource: string) => void;
}

const SvgDiagram: React.FC<SvgDiagramProps> = ({ children, onEditSvg }) => {
  const [background, setBackground] = useState<SvgBackground>('transparent');

  const sanitized = useMemo(() => {
    return DOMPurify.sanitize(children.trim(), {
      ADD_TAGS: ['svg', 'circle', 'rect', 'path', 'line', 'polygon', 'polyline', 'ellipse', 'text', 'tspan', 'g', 'defs',
        'linearGradient', 'radialGradient', 'stop', 'use', 'clipPath', 'mask', 'pattern', 'symbol', 'marker',
        'animate', 'animateTransform', 'animateMotion', 'filter', 'feGaussianBlur', 'feOffset', 'feMerge',
        'feMergeNode', 'feColorMatrix', 'feBlend', 'image', 'foreignObject', 'switch', 'title', 'desc',
        'metadata', 'style'],
      ADD_ATTR: ['d', 'cx', 'cy', 'r', 'rx', 'ry', 'x', 'y', 'x1', 'x2', 'y1', 'y2', 'width', 'height',
        'viewBox', 'fill', 'stroke', 'stroke-width', 'stroke-linecap', 'stroke-linejoin', 'stroke-dasharray',
        'opacity', 'transform', 'dx', 'dy', 'text-anchor', 'font-size', 'font-family', 'font-weight',
        'font-style', 'text-decoration', 'dominant-baseline', 'alignment-baseline', 'clip-path',
        'clip-rule', 'fill-rule', 'fill-opacity', 'stroke-opacity', 'marker-end', 'marker-start',
        'marker-mid', 'filter', 'offset', 'stdDeviation', 'in', 'in2', 'mode', 'result', 'values',
        'keyTimes', 'keySplines', 'repeatCount', 'begin', 'dur', 'attributeName', 'from', 'to',
        'gradientUnits', 'gradientTransform', 'xlink:href', 'href', 'style', 'class', 'id',
        'vector-effect', 'shape-rendering', 'text-rendering'],
    });
  }, [children]);

  const handleBackgroundChange = (_event: React.MouseEvent<HTMLElement>, value: SvgBackground | null): void => {
    if (value !== null) {
      setBackground(value);
    }
  };

  return (
    <Box sx={{ my: 2 }}>
      <Box sx={{ display: 'flex', justifyContent: 'flex-end', alignItems: 'center', gap: 0.5, mb: 0.5 }}>
        <ToggleButtonGroup value={background} exclusive size="small" onChange={handleBackgroundChange}>
          <Tooltip title="Light background">
            <ToggleButton value="light" aria-label="Light background">
              <LightMode fontSize="small" />
            </ToggleButton>
          </Tooltip>
          <Tooltip title="Dark background">
            <ToggleButton value="dark" aria-label="Dark background">
              <DarkMode fontSize="small" />
            </ToggleButton>
          </Tooltip>
          <Tooltip title="Transparent background">
            <ToggleButton value="transparent" aria-label="Transparent background">
              <CheckBoxOutlineBlank fontSize="small" />
            </ToggleButton>
          </Tooltip>
        </ToggleButtonGroup>
        {onEditSvg && (
          <Tooltip title="Edit with AI">
            <IconButton
              size="small"
              aria-label="Edit SVG"
              onClick={(): void => onEditSvg(children.trim())}
              sx={{
                color: 'text.secondary',
                '&:hover': {
                  bgcolor: (theme) => (theme.palette.mode === 'dark' ? 'rgba(255, 255, 255, 0.1)' : 'rgba(0, 0, 0, 0.05)'),
                },
              }}
            >
              <Edit fontSize="small" />
            </IconButton>
          </Tooltip>
        )}
      </Box>
      <Box
        dangerouslySetInnerHTML={{ __html: sanitized }}
        sx={{
          display: 'flex',
          justifyContent: 'center',
          '& svg': {
            maxWidth: '100%',
            height: 'auto',
            backgroundColor: SVG_BACKGROUND_COLORS[background],
            borderRadius: 1,
          },
        }}
      />
    </Box>
  );
};

/**
 * Ensures all fenced code blocks are properly closed.
 * If the LLM forgets a closing ```, react-markdown would swallow the rest
 * of the content into the code block — everything after the unclosed fence
 * would render as plain text instead of formatted markdown.
 *
 * Uses two-phase approach:
 * 1. General: balance any unmatched ``` fences by appending at end.
 * 2. SVG-specific: when a ```svg fence opens and an </svg> tag appears
 *    inside it, insert a closing ``` right after </svg> so the remaining
 *    content is properly parsed as markdown.
 */
function ensureClosedFences(content: string): string {
  const lines = content.split('\n');
  const openFences: string[] = [];
  const result: string[] = [];
  let svgFenceOpen = false;

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const trimmed = line.trim();
    const isFence = trimmed.startsWith('```');

    if (isFence) {
      if (openFences.length === 0) {
        openFences.push('```');
        if (trimmed === '```svg') {
          svgFenceOpen = true;
        }
      } else {
        openFences.pop();
        svgFenceOpen = false;
      }
      result.push(line);
    } else if (svgFenceOpen && trimmed.endsWith('</svg>')) {
      const lookAhead = lines.slice(i + 1, i + 5).map((l) => l.trim());
      const hasCloseFence = lookAhead.some((la) => la.startsWith('```'));
      result.push(line);
      if (!hasCloseFence) {
        result.push('```');
        openFences.pop();
        svgFenceOpen = false;
      }
    } else {
      result.push(line);
    }
  }

  if (openFences.length > 0) {
    result.push('```');
  }

  return result.join('\n');
}

/**
 * Escapes $ signs that appear to be currency markers (followed by a digit)
 * so remark-math doesn't misinterpret them as inline math delimiters.
 * Proper $...$ math expressions are unaffected since the opening $ is
 * typically followed by a letter or backslash, not a digit.
 */
function escapeCurrencyDollars(content: string): string {
  return content.replace(/\$(?=\d)/g, '\\$');
}

const MarkdownWithCode: React.FC<MarkdownProps> = ({ children, fontSize = 16, disableMermaid = false, disableSvg = false, onEditSvg }) => {
  const theme = useTheme();
  const themeMode = useAuthStore((s) => s.themeMode);

  useEffect(() => {
    mermaid.initialize({
      startOnLoad: false,
      theme: themeMode === 'dark' ? 'dark' : 'default',
      securityLevel: 'loose',
    });
  }, [themeMode]);
  const markdownComponents: Components = {
    p: ({ children }) => (
      <Typography variant="body2" sx={{ lineHeight: 1.4, mb: 1, fontSize: `${fontSize}px` }} component="p">
        {children}
      </Typography>
    ),
    h1: ({ children }) => (
      <Typography variant="h5" sx={{ fontWeight: 'bold', mt: 2, mb: 1, fontSize: `${fontSize * 1.5}px` }}>
        {children}
      </Typography>
    ),
    h2: ({ children }) => (
      <Typography variant="h6" sx={{ fontWeight: 'bold', mt: 1.5, mb: 1, fontSize: `${fontSize * 1.3}px` }}>
        {children}
      </Typography>
    ),
    h3: ({ children }) => (
      <Typography variant="subtitle1" sx={{ fontWeight: 'bold', mt: 1, mb: 0.5, fontSize: `${fontSize * 1.1}px` }}>
        {children}
      </Typography>
    ),
    li: ({ children }) => (
      <li style={{ marginBottom: '0.25em', lineHeight: 1.4, fontSize: `${fontSize}px` }}>
        <Typography variant="body2" component="span" sx={{ fontSize: 'inherit' }}>
          {children}
        </Typography>
      </li>
    ),

    code({
      inline,
      className,
      children,
      style: _inlineCodeStyle,
      ...props
    }: React.ComponentPropsWithoutRef<'code'> & { inline?: boolean }): React.ReactElement {
      const match = /language-(\w+)/.exec(className ?? '');
      const codeString = String(children).replace(/\n$/, '');
      const darkSyntaxStyle: Record<string, CSSProperties> = {
        ...oneDark,
        comment: { ...oneDark.comment, color: '#7f8ea3' },
        'block-comment': { ...oneDark['block-comment'], color: '#7f8ea3' },
        prolog: { ...oneDark.prolog, color: '#7f8ea3' },
      };
      const lightSyntaxStyle = oneLight as Record<string, CSSProperties>;
      const syntaxStyle: Record<string, CSSProperties> = theme.palette.mode === 'dark' ? darkSyntaxStyle : lightSyntaxStyle;
      return !inline && match ? (
        match[1] === 'mermaid' && !disableMermaid ? (
          <MermaidDiagram key={codeString}>{codeString}</MermaidDiagram>
        ) : match[1] === 'svg' && !disableSvg ? (
          <SvgDiagram key={codeString} onEditSvg={onEditSvg}>{codeString}</SvgDiagram>
        ) : (
        <Box
          sx={{
            position: 'relative',
            overflowX: 'auto',
            my: 1,
            fontSize: `${Math.max(12, fontSize - 2)}px`,
            borderRadius: 1,
            '&:hover .copy-button': { opacity: 1 },
          }}
        >
          <CopyButton text={codeString} />
          <SyntaxHighlighter
            language={match[1]}
            style={syntaxStyle}
            PreTag="div"
            customStyle={{
              whiteSpace: 'pre',
              padding: '1em',
              margin: 0,
              lineHeight: '1.4',
            }}
            wrapLongLines={false}
            {...props}
          >
            {codeString}
          </SyntaxHighlighter>
        </Box>
        )
      ) : (
        <code
          className={className}
          style={{
            backgroundColor: theme.palette.mode === 'dark' ? '#333' : alpha(theme.palette.primary.main, 0.08),
            color: theme.palette.mode === 'dark' ? '#e0e0e0' : theme.palette.primary.main,
            padding: '0.2em 0.4em',
            borderRadius: 4,
            fontSize: `${Math.max(12, fontSize - 2)}px`,
          }}
          {...props}
        >
          {children}
        </code>
      );
    },
  };

  return (
    <Box sx={{ overflowWrap: 'break-word', wordBreak: 'normal' }}>
      <ReactMarkdown remarkPlugins={[remarkGfm, remarkMath]} rehypePlugins={[rehypeKatex]} components={markdownComponents}>
        {escapeCurrencyDollars(ensureClosedFences(children))}
      </ReactMarkdown>
    </Box>
  );
};

export default MarkdownWithCode;